### Depth-First Search (DFS)
DFS is a simple algorithm that explores as far as possible along each branch before backtracking. It can be useful for finding a path to the goal if it's closer to the starting point.

### Breadth-First Search (BFS)
BFS is a more reliable algorithm that explores the neighbor nodes first before moving to the next level of depth. BFS is commonly used for finding the shortest path in an unweighted grid.

Let's implement both of these algorithms for a grid-based pathfinding scenario.

```python
from collections import deque

class Grid:
    def __init__(self, grid):
        self.grid = grid
        self.ROWS = len(grid)
        self.COLS = len(grid[0])
        self.visited = [[False for _ in range(self.COLS)] for _ in range(self.ROWS)]
        self.start = None
        self.goal = None
        self.path = []

    def set_start(self, x, y):
        self.start = (x, y)
        self.visited[x][y] = True

    def set_goal(self, x, y):
        self.goal = (x, y)

    def is_valid(self, x, y):
        if x < 0 or y < 0 or x >= self.ROWS or y >= self.COLS:
            return False
        if self.visited[x][y]:
            return False
        return True

    def dfs(self, x, y):
        self.visited[x][y] = True
        self.path.append((x, y))

        if (x, y) == self.goal:
            return True

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if self.is_valid(nx, ny):
                if self.dfs(nx, ny):
                    return True

        self.path.pop()
        return False

    def bfs(self, x, y):
        self.path.append((x, y))
        queue = deque([(x, y)])
        self.visited[x][y] = True

        while queue:
            x, y = queue.popleft()
            if (x, y) == self.goal:
                return True

            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if self.is_valid(nx, ny):
                    queue.append((nx, ny))
                    self.visited[nx][ny] = True

        return False

def find_path(grid, start, goal):
    grid.set_start(*start)
    grid.set_goal(*goal)
    if grid.dfs(*start):
        return grid.path
    elif grid.bfs(*start):
        return grid.path
    else:
        return None

