### Depth-First Search (DFS)

DFS is a simple algorithm that explores as far as possible along each branch before backtracking. It can be useful in scenarios where a path to the goal is desired, or when the goal is known to be at a certain depth in the search space.

```python
class Graph:
    def __init__(self, graph_dict=None):
        if graph_dict is None:
            graph_dict = {}
        self.graph_dict = graph_dict

    def add_vertex(self, vertex):
        if vertex not in self.graph_dict:
            self.graph_dict[vertex] = []

    def add_edge(self, vertex1, vertex2):
        if vertex1 in self.graph_dict:
            self.graph_dict[vertex1].append(vertex2)
        else:
            self.graph_dict[vertex1] = [vertex2]
        if vertex2 in self.graph_dict:
            self.graph_dict[vertex2].append(vertex1)
        else:
            self.graph_dict[vertex2] = [vertex1]

    def dfs(self, start_vertex, target='end'):
        visited = set()
        stack = [start_vertex]

        while stack:
            vertex = stack.pop()
            if vertex == target:
                return f"Target {target} found at {vertex}"
            if vertex not in visited:
                visited.add(vertex)
                stack.extend(self.graph_dict[vertex])
        return f"Target {target} not found"

# Example usage:
g = Graph()
g.add_edge('A', 'B')
g.add_edge('A', 'C')
g.add_edge('B', 'D')
g.add_edge('B', 'E')
g.add_edge('C', 'F')
g.add_edge('D', 'G')
g.add_edge('E', 'G')

print(g.dfs('A'))
```

Certainly! One of the most common path search algorithms is the Breadth-First Search (BFS). BFS is a simple and effective algorithm for finding the shortest path in an unweighted graph from a start node to a goal node. Here's a Python implementation of BFS:

```python
class Graph:
    def __init__(self, graph_dict=None, directed=True):
        self.graph_dict = graph_dict or {}
        self.directed = directed
        if not directed:
            self.make_undirected()

    def make_undirected(self):
        for a in list(self.graph_dict.keys()):
            for (b, dist) in self.graph_dict[a].items():
                self.graph_dict.setdefault(b, {})[a] = dist

    def connect(self, A, B, distance=1):
        self.graph_dict.setdefault(A, {})[B] = distance
        if not self.directed:
            self.graph_dict.setdefault(B, {})[A] = distance

    def get(self, a, b=None):
        links = self.graph_dict.get(a)
        if b is None:
            return links
        else:
            return links.get(b)

    def nodes(self):
        return list(self.graph_dict.keys())

def bfs(graph, start, goal):
    if goal not in graph.nodes():
        raise ValueError("Invalid goal node")

    # Keep track of visited nodes
    visited = []

    # Keep track of nodes to be checked
    queue = [[start]]

    # If the desired node is the start node, there's nothing to do
    if start == goal:
        return "Start and goal are the same"

    # Loop until we find the goal
    while queue:
        # Pop the first path from the queue
        path = queue.pop(0)
        # Get the last node from the path
        node = path[-1]
        if node not in visited:
            neighbors = graph.get(node)
            # Go through all the neighbors
            for (neighbor, dist) in neighbors.items():
                new_path = list(path)
                new_path.append(neighbor)
                queue.append(new_path)
                # If the neighbor is the goal, return the path
                if neighbor == goal:
                    return new_path
            # Mark the node as visited
            visited.append(node)

    # If the goal was never reached, return failure
    return "No path found"

# Example usage:
graph_dict = {
    'A': {'B': 1, 'C': 3, 'D': 7},
    'B': {'A': 1, 'C': 2, 'D': 6},
    'C': {'A': 3, 'B': 2, 'D': 4},
    'D': {'A': 7, 'B': 6, 'C': 4}
}

graph = Graph(graph_dict)
start_node = 'A'
goal_node = 'D'
path = bfs(graph, start_node, goal_node)

if isinstance(path, str):
    print(path)
else:
    print("Path from", start_node, "to", goal_node, ":", "->".join(path))
```

