```python
class Graph:
    def __init__(self):
        self.graph = {}

    def add_edge(self, u, v):
        if u in self.graph:
            self.graph[u].append(v)
        else:
            self.graph[u] = [v]

    def dfs(self, start_vertex, target_vertex=None):
        visited = set()
        self._dfs(start_vertex, visited, target_vertex)
        return visited

    def _dfs(self, current_vertex, visited, target_vertex):
        if current_vertex == target_vertex:
            return visited.add(current_vertex)

        if current_vertex in visited:
            return

        visited.add(current_vertex)
        if current_vertex in self.graph:
            for neighbor in self.graph[current_vertex]:
                self._dfs(neighbor, visited, target_vertex)

        return visited

# Example usage
if __name__ == "__main__":
    graph = Graph()
    graph.add_edge('A', 'B')
    graph.add_edge('B', 'C')
    graph.add_edge('C', 'D')
    graph.add_edge('D', 'E')

    # Perform DFS from node 'A' to find all reachable nodes
    path = graph.dfs('A')
    print("DFS Path:", path)
```

Certainly! A popular path search algorithm is the Breadth-First Search (BFS). BFS is particularly useful for finding the shortest path in an unweighted graph. Below is a Python implementation of the BFS algorithm:

```python
class Graph:
    def __init__(self, graph_dict=None, directed=True):
        self.graph_dict = graph_dict or {}
        self.directed = directed
        if not directed:
            self.make_undirected()

    def make_undirected(self):
        """Make a directed graph into an undirected graph by adding symmetric edges."""
        for a in list(self.graph_dict.keys()):
            for (b, dist) in self.graph_dict[a].items():
                self.add_edge(b, a, dist)

    def add_vertex(self, vertex):
        """Add a vertex to the graph."""
        if vertex not in self.graph_dict:
            self.graph_dict[vertex] = {}

    def add_edge(self, start, end, distance=1):
        """Add a directed edge to the graph."""
        self.graph_dict[start][end] = distance
        if not self.directed:
            self.graph_dict[end][start] = distance

    def bfs(self, start):
        """Return a list of vertices that BFS reaches, starting from start vertex."""
        # Keep track of all visited vertices
        explored = []
        # Keep track of vertices to be checked
        queue = [start]
        # Keep looping until there are vertices still to be checked
        while queue:
            # Dequeue a vertex from the queue
            vertex = queue.pop(0)
            if vertex not in explored:
                # If not already visited
                explored.append(vertex)
                neighbors = self.graph_dict[vertex]
                # Add vertices with unvisited neighbors
                for neighbor in neighbors.keys():
                    if neighbor not in explored and neighbor not in queue:
                        queue.append(neighbor)
        return explored


# Example usage:
if __name__ == "__main__":
    g = Graph()  # Create a new graph

    edges = [
        ('A', 'B', 1), ('A', 'C', 1),
        ('B', 'D', 1), ('B', 'E', 1),
        ('C', 'F', 1), ('C', 'G', 1),
        ('D', 'H', 1), ('D', 'I', 1), ('D', 'J', 1),
        ('E', 'K', 1), ('E', 'L', 1)
    ]

    for start, end, dist in edges:
        g.add_edge(start, end, dist)  # Add edges to the graph

    # Test the BFS function
    print("BFS starting from vertex 'A':", g.bfs('A'))
```

