from collections import deque

def bfs(graph, start, goal):
    if start == goal:
        return [start]  # If the start node is the goal node, return the start node as the path

    visited = set()  # Set to keep track of visited nodes
    queue = deque([(start, [start])])  # Queue for BFS, contains (node, path) pairs

    while queue:
        (current, path) = queue.popleft()

        if current not in visited:
            visited.add(current)
            if current == goal:
                return path  # Return the path if the goal node is found

            # Add all adjacent nodes to the queue (for BFS, we add them in the order they are found)
            for neighbor in graph[current]:
                queue.append((neighbor, path + [neighbor]))

    return None  # If goal node is not reachable

