class Graph:
    def __init__(self, edges):
        self.adj_list = {}
        self.add_edges(edges)

    def add_edges(self, edges):
        for src, dest in edges:
            if src not in self.adj_list:
                self.adj_list[src] = []
            if dest not in self.adj_list:
                self.adj_list[dest] = []
            self.adj_list[src].append(dest)
            self.adj_list[dest].append(src)

    def bfs(self, start, target):
        if start not in self.adj_list or target not in self.adj_list:
            return None  # Nodes not present in the graph

        queue = deque()
        visited = set()
        queue.append((start, [start]))  # Node and path taken to reach it

        while queue:
            current_node, path = queue.popleft()
            for neighbor in self.adj_list[current_node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    if neighbor == target:
                        return path + [neighbor]  # Return the path if target is reached
                    queue.append((neighbor, path + [neighbor]))

        return None  # Target not reachable

